{"task": "customer-fk", "steps": [
  {"note": "Add the foreign key as NOT VALID: catalog-only, no scan of the 10M orders, so it holds its SHARE ROW EXCLUSIVE lock on orders/customers for only milliseconds. From here on every new or updated order is checked. Each attempt waits at most 200 ms for the lock (so app queries never queue behind it for longer) and is retried up to 60 times. Skips if the constraint already exists, so the step can be re-run.",
   "sql": "DO $$ DECLARE attempt int := 0; BEGIN IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.orders'::regclass AND conname = 'orders_customer_id_fkey') THEN RAISE NOTICE 'constraint already exists'; RETURN; END IF; LOOP BEGIN PERFORM set_config('lock_timeout', '200ms', true); ALTER TABLE public.orders ADD CONSTRAINT orders_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers (id) NOT VALID; RETURN; EXCEPTION WHEN lock_not_available THEN attempt := attempt + 1; IF attempt >= 60 THEN RAISE; END IF; PERFORM pg_sleep(0.5); END; END LOOP; END $$;"},
  {"note": "Validate the existing rows. VALIDATE CONSTRAINT takes only SHARE UPDATE EXCLUSIVE on orders and ROW SHARE on customers, which do not conflict with the app's reads and inserts, so traffic keeps flowing while it scans. No statement timeout, since the scan of 10M rows can take a while. If any order pointed at a missing customer this would fail and change nothing; checked beforehand: there are none.",
   "sql": "SET statement_timeout = 0; SET lock_timeout = 0; ALTER TABLE public.orders VALIDATE CONSTRAINT orders_customer_id_fkey;"},
  {"note": "Check that the constraint exists and is validated; fail loudly otherwise.",
   "sql": "DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.orders'::regclass AND conname = 'orders_customer_id_fkey' AND contype = 'f' AND convalidated) THEN RAISE EXCEPTION 'orders_customer_id_fkey missing or not validated'; END IF; END $$;"}
]}
